"""Glowglass product, privacy and support pages. Safe to run independently."""
from pathlib import Path
from bs4 import BeautifulSoup
from page_template import page
ROOT=Path(__file__).resolve().parents[1]
BASE='/assets/apps/glowglass/'
def build(_page=None):
 body='''<link rel="stylesheet" href="/assets/apps/glowglass/page.css">
<section class="glow-hero"><div><p class="eyebrow">Offline light puzzles for Android · Coming soon</p><h1>Glowglass:<br>Light Puzzles</h1><p class="glow-tagline">Turn. Connect.<br>Light it up.</p><p>Turn a mirror. Move a piece of glass. Watch cyan, gold and violet find their way home. Sixty optical puzzles invite you to slow down, look closer, and think a few turns ahead.</p><p><a class="button" href="#inside">Explore the puzzles</a> <a class="glow-secondary" href="/glowglass/support/">How to play</a></p><p class="glow-status">In development. Planned as a $0.99 one-time purchase, with no ads or in-app purchases. Not yet available on Google Play; final regional pricing may differ.</p></div><figure><img src="/assets/apps/glowglass/game.png" width="720" height="1280" alt="Glowglass gameplay: glass mirrors route cyan, gold and violet beams across a vivid blue arcade board"><figcaption>Actual development gameplay · 1.0.2 candidate</figcaption></figure></section>
<section class="glow-intro" id="inside"><p class="eyebrow">Simple to touch. Satisfying to untangle.</p><h2>Let the light do the talking.</h2><p>Tap glass to rotate it. Drag a dotted mirror into an empty socket. The beam changes immediately, so every experiment gives you something to think about. Your goal is to illuminate every receiver with its labeled color at the same time.</p><p>There is no timer, energy meter or penalty for trying again. Undo takes you back one move; free, two-stage hints point toward a solution without making the move for you.</p></section>
<section><h2>Six chapters. Sixty different connections.</h2><div class="glow-chapters"><article><span>First light</span><h3>Learn by touching</h3><p>Meet mirrors, splitters, color filters and three-way prisms in ten introductory puzzles.</p></article><article><span>Reflections</span><h3>Look further ahead</h3><p>Follow longer paths and discover how a small turn changes the whole route.</p></article><article><span>Echoes</span><h3>Think in two directions</h3><p>A splitter carries light straight ahead and around a corner. Both paths matter.</p></article><article><span>Spectrum</span><h3>Give each color a home</h3><p>Route cyan, gold and violet through prisms, mirrors and filters.</p></article><article><span>Moving light</span><h3>Change your perspective</h3><p>Move glass between sockets, then choose the angle that completes the connection.</p></article><article><span>Resonance</span><h3>Bring it all together</h3><p>Linked turns and movable mirrors combine into the most involved puzzles.</p></article></div></section>
<section class="glow-bottom"><div><h2>Your pace. Your space.</h2><p>All chapters are open to explore. The game remembers unfinished boards and your personal best move counts on this device. Return for a short break or work through a whole chapter.</p><p>Color labels accompany the light, sound is optional, and animated light can be switched off. The game works offline without an account, advertising, analytics or a gameplay server.</p><p>Progress stays local: clearing app storage or uninstalling removes it. There is no cloud restore.</p><p><a href="/glowglass/privacy/">Read the privacy policy</a> · <a href="mailto:tripperdeelabs@gmail.com?subject=Glowglass">Contact the developer</a></p></div><figure><img src="/assets/apps/glowglass/collection.png" width="720" height="1280" loading="lazy" alt="Glowglass collection menu with ten puzzle cards and chapter navigation"><figcaption>Actual development collection screen</figcaption></figure></section>'''
 page('/glowglass/','Glowglass: Light Puzzles — Offline Android Puzzle Game','Explore 60 optical puzzles in Glowglass for Android. Tap mirrors, move glass and guide colored light. No ads, no timer, offline play. Coming soon.',body,'https://tripperdeelabs.com'+BASE+'game.png')
 page('/glowglass/privacy/','Glowglass privacy policy','How Glowglass stores puzzle progress locally, handles support and uses no ads, accounts or gameplay analytics.','''<section><h1>Glowglass privacy policy</h1><p>Updated November 25, 2026. This policy covers Glowglass: Light Puzzles, Android version 1.0.2, supplied by TripperDeeLabs. The release candidate uses package com.tripperdeelabs.glowglass; local test builds use com.tripperdeelabs.glowglass.test.</p><h2>On-device game data</h2><p>Puzzle progress, unfinished boards, personal best move counts, last-played puzzle, sound and animation settings are stored in the app’s private storage on your device. TripperDeeLabs does not receive these records and does not operate a gameplay server. There is no account or sign-in.</p><h2>No advertising or analytics</h2><p>The game includes no advertising, analytics, consent-management or in-app billing SDK. It requests no Android permissions, including internet access. It does not access your location, contacts, camera, microphone or advertising identifier. Puzzles work offline. There is no chat, sharing, user-generated content or online leaderboard.</p><h2>Purchase and store services</h2><p>The planned product is a one-time paid download through Google Play, with no in-app purchases or subscriptions. Google Play handles payment and its own account and store records under Google’s policies. The game does not receive payment-card details. A public store release has not yet occurred.</p><h2>Privacy and support links</h2><p>Choosing Privacy policy opens the website in your browser. Choosing Email support opens your email app with a draft; nothing is sent automatically. These other apps and the website may use a connection. If you send an email, we receive the address and information you choose to provide and use them to respond. Please do not send payment details or passwords. Website practices are described separately in the <a href="/privacy/">website privacy policy</a>.</p><h2>Retention and deletion</h2><p>Game records remain on your device until you clear app storage or uninstall. Android app backup is disabled; manufacturer migration behavior can vary. We cannot recover deleted puzzle progress. Buying or reinstalling the app does not restore local progress. To request deletion of support correspondence, contact us. Google handles requests about information Google holds.</p><h2>Children and contact</h2><p>The game is designed for people who enjoy thoughtful spatial puzzles. It does not request age or date of birth, and has no child-specific data collection. A parent or guardian may contact us on a child’s behalf. Contact <a href="mailto:tripperdeelabs@gmail.com">tripperdeelabs@gmail.com</a> for support or privacy questions.</p><p><a href="/glowglass/">Game overview</a> · <a href="/glowglass/support/">Support</a></p></section>''')
 page('/glowglass/support/','Glowglass support and how to play','Learn Glowglass mirror, prism, filter and dragging controls, hints, saved progress and offline play.','''<section><h1>Glowglass support</h1><p>Glowglass: Light Puzzles 1.0.2 is currently a development candidate, not a public Google Play release.</p><h2>Make your first connection</h2><p>Choose Begin with light. Tap the mirror once and watch the cyan beam reach its receiver. Every puzzle is complete when all receivers have exactly their labeled color. C means cyan, G gold, V violet and W white. Light updates after every gesture.</p><h2>Glass pieces</h2><ul><li>Mirrors reflect light through a right angle. Tap to switch between their two angles.</li><li>Splitters marked + send light straight ahead and along the reflected path.</li><li>Prisms separate white light into cyan, gold and violet through three labeled ports. Tap to rotate all ports together.</li><li>Filters pass one color. Tap to cycle cyan, gold and violet.</li><li>Mirrors marked A turn together. A single tap changes both.</li><li>Mirrors with three dots can move. Drag one into an empty dashed socket; the beam previews a valid placement before release. An invalid drop keeps the original position.</li></ul><h2>Hints, undo and restart</h2><p>A little hint first highlights a piece. Choose it again for a specific step toward one authored solution. Hints are free and never make the move for you. Undo reverses a move, including Restart, during the current puzzle session. Returning Home or reopening a puzzle starts a new undo history. Restart leaves your previous completion record intact.</p><h2>Chapters and records</h2><p>Use the arrows beside the chapter name on Home to browse six collections of ten puzzles. All are open. Continue returns to your last unfinished puzzle, or the next unfinished puzzle after a completion. Your best move count and chapter completion remain on this device.</p><h2>Comfort and privacy</h2><p>Settings &amp; about includes Sound and Light animation switches, privacy and email links. Disabling light animation removes moving beam sparks; all puzzle rules and controls remain available. Android Back closes a panel, returns from a puzzle to Home, or offers Save &amp; exit.</p><h2>Keep your progress</h2><p>Do not clear app storage or uninstall when troubleshooting if you want to retain progress. There is no account or cloud restore. The separate test and production packages have separate saves. A storage warning means progress could not be saved; check free device space. An unreadable save is not overwritten automatically.</p><h2>Contact</h2><p>Email <a href="mailto:tripperdeelabs@gmail.com?subject=Glowglass%20support">tripperdeelabs@gmail.com</a> with your version, device model, puzzle number and what happened. Nothing is emailed automatically.</p><p><a href="/glowglass/">Game overview</a> · <a href="/glowglass/privacy/">Privacy policy</a></p></section>''')
 for file in (ROOT/'glowglass').rglob('index.html'):
  s=file.read_text().replace('<body>','<body><a class="skip-link" href="#main-content">Skip to main content</a>').replace('<main class="wrap">','<main id="main-content" tabindex="-1" class="wrap">');file.write_text(s)
 home=ROOT/'index.html';soup=BeautifulSoup(home.read_text(),'html.parser');listing=soup.select_one('#in-development .app-directory');assert listing is not None
 old=soup.select_one('#glowglass-card')
 if old:old.decompose()
 card=BeautifulSoup('''<li id="glowglass-card"><a class="directory-preview" href="/glowglass/"><img src="/assets/apps/glowglass/game.png" width="720" height="1280" loading="lazy" alt="Glowglass light puzzle gameplay"></a><div class="directory-copy"><h3><a href="/glowglass/">Glowglass: Light Puzzles</a></h3><p class="availability">Coming soon</p><p>Tap mirrors, move glass and guide colored light through 60 offline puzzles. Six chapters, simple gestures, free hints and no timer or ads.</p><p><a href="/glowglass/">Explore the game</a> · <a href="/glowglass/privacy/">Privacy</a></p></div></li>''','html.parser').li
 listing.insert(0,card);home.write_text(str(soup))
 privacy=ROOT/'privacy/apps/index.html';s=privacy.read_text()
 if '/glowglass/privacy/' not in s:s=s.replace('</main>','<section><h2>Glowglass</h2><p><a href="/glowglass/privacy/">Glowglass: Light Puzzles privacy policy</a> — local puzzle progress, no ads or analytics.</p></section></main>');privacy.write_text(s)
 llms=ROOT/'llms.txt';s=llms.read_text()
 if '/glowglass/' not in s:s+='\n## Glowglass (coming soon)\n\n- [Glowglass: Light Puzzles](https://tripperdeelabs.com/glowglass/): 60 offline optical puzzles for Android; not yet released.\n- [Privacy](https://tripperdeelabs.com/glowglass/privacy/)\n- [Support](https://tripperdeelabs.com/glowglass/support/)\n';llms.write_text(s)
 sitemap=ROOT/'sitemap.xml';s=sitemap.read_text()
 for path in ['glowglass/','glowglass/privacy/','glowglass/support/']:
  url='https://tripperdeelabs.com/'+path
  if url+'</loc>' not in s:s=s.replace('</urlset>','  <url><loc>'+url+'</loc></url>\n</urlset>')
 sitemap.write_text(s)
if __name__=='__main__':build()
